// Extrae el mensaje entrante del payload de WhatsApp Cloud API.
// Devuelve [] para eventos sin mensaje (p. ej. estados "sent"/"delivered"/"read").
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];

// Deduplicación: Meta puede reenviar el mismo webhook.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || [];
if (store.processed.includes(msg.id)) return [];
store.processed.push(msg.id);
store.processed = store.processed.slice(-500);

const contactName = value.contacts?.[0]?.profile?.name || '';
let text = '';
let needsAI = true;
let directReply = '';

switch (msg.type) {
  case 'text':
    text = msg.text?.body || '';
    break;
  case 'interactive':
    text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
    break;
  case 'button':
    text = msg.button?.text || '';
    break;
  default:
    // Audio, imagen, documento, ubicación, etc.: se avisa al modelo para que responda según el system prompt.
    text = `[El usuario envió un mensaje de tipo "${msg.type}" que el asistente no puede leer.]`;
}

if (!text.trim()) {
  needsAI = false;
  directReply = 'Disculpe, no pude leer su mensaje. ¿Podría escribirnos su consulta en texto, por favor?';
}

return [{
  json: {
    from: msg.from,
    messageId: msg.id,
    contactName,
    phoneNumberId: value.metadata?.phone_number_id,
    text: text.slice(0, 4000),
    needsAI,
    directReply,
  },
}];

// Arma la solicitud a la Claude Messages API con el historial de la conversación.
const fs = require('fs');
const input = $input.first().json;

const promptPath = $env.SYSTEM_PROMPT_PATH || '/data/system_prompt.md';
let systemPrompt;
try {
  systemPrompt = fs.readFileSync(promptPath, 'utf8');
} catch (e) {
  throw new Error(`No se pudo leer el system prompt en ${promptPath}: ${e.message}`);
}

// Memoria simple en static data del workflow (solo persiste en ejecuciones de producción).
// Para producción con volumen, reemplazar por Redis/Postgres (ver README).
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

let convo = store.conversations[input.from];
if (!convo || Date.now() - convo.updatedAt > ttlMs) {
  convo = { messages: [], updatedAt: Date.now() };
}

// Contexto dinámico (fecha/hora) solo en el turno actual, para no invalidar la caché del system prompt.
const now = new Date().toLocaleString('es-PE', {
  timeZone: $env.BUSINESS_TIMEZONE || 'America/Lima',
  dateStyle: 'full',
  timeStyle: 'short',
});
const nameNote = input.contactName ? ` | Nombre de perfil en WhatsApp: ${input.contactName}` : '';
const currentTurn = `[Contexto del sistema: fecha y hora actual: ${now}${nameNote}]\n\n${input.text}`;

const messages = [...convo.messages, { role: 'user', content: currentTurn }];

const anthropicBody = {
  model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5-5',
  max_tokens: parseInt($env.ANTHROPIC_MAX_TOKENS || '8000', 10),
  thinking: { type: 'adaptive' },
  output_config: { effort: $env.ANTHROPIC_EFFORT || 'low' },
  // Si un clasificador de seguridad rechaza la solicitud, la API la reintenta en el modelo recomendado.
  fallbacks: 'default',
  system: [
    { type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } },
  ],
  messages,
};

return [{ json: { ...input, anthropicBody, history: convo.messages, maxTurns } }];

// Procesa la respuesta de Claude, extrae el bloque <cita> y actualiza la memoria.
const res = $input.first().json;
const ctx = $('Preparar solicitud Claude').first().json;

const FALLBACK = 'Disculpe, en este momento no puedo procesar su mensaje. Un miembro de nuestro equipo le contactará en horario de atención. Gracias por escribir a JS CONSULTORES Y ABOGADOS.';

let reply = '';
let ok = false;

if (res.error || !Array.isArray(res.content)) {
  reply = FALLBACK;
} else if (res.stop_reason === 'refusal') {
  reply = 'Disculpe, no puedo ayudarle con esa solicitud por este medio. Si lo desea, puedo coordinar una consulta con uno de nuestros abogados.';
} else {
  // Solo bloques de texto: la respuesta puede incluir bloques "thinking" que no se envían.
  reply = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
  ok = reply.length > 0;
  if (!ok) reply = FALLBACK;
}

// Extraer la solicitud de cita (si la hay) y retirarla del mensaje visible.
let appointment = null;
const match = reply.match(/<cita>([\s\S]*?)<\/cita>/);
if (match) {
  try { appointment = JSON.parse(match[1]); } catch (e) { appointment = { raw: match[1] }; }
  reply = reply.replace(match[0], '').trim();
}

// WhatsApp admite hasta 4096 caracteres por mensaje de texto.
if (reply.length > 4000) reply = reply.slice(0, 3990) + '…';

// Guardar el turno en memoria solo si Claude respondió correctamente.
if (ok) {
  const store = $getWorkflowStaticData('global');
  store.conversations = store.conversations || {};
  const msgs = [
    ...ctx.history,
    { role: 'user', content: ctx.text },
    { role: 'assistant', content: reply },
  ];
  // Recortar por pares para que el historial siempre empiece con un turno "user".
  let trimmed = msgs.slice(-ctx.maxTurns);
  if (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  store.conversations[ctx.from] = { messages: trimmed, updatedAt: Date.now() };
}

return [{
  json: {
    from: ctx.from,
    phoneNumberId: ctx.phoneNumberId,
    reply,
    appointment,
    hasAppointment: !!appointment,
    usage: res.usage || null,
  },
}];
